actions.script:
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

// Read Razorpay config from system settings
def keyId = ec.entity.find("zenith.erp.base.CompanySettings")
    .condition("organizationPartyId", "ZETAERP")
    .condition("settingKey", "RAZORPAY_KEY_ID").disableAuthz().one()?.settingValue
def keySecret = ec.entity.find("zenith.erp.base.CompanySettings")
    .condition("organizationPartyId", "ZETAERP")
    .condition("settingKey", "RAZORPAY_KEY_SECRET").disableAuthz().one()?.settingValue

if (!keyId || !keySecret) {
    // ZE-SUB-007/MS-040: a TENANT clicks Pay Now, so surface a tenant-appropriate message and keep
    // the operator-facing config detail (which key is missing / where) in the server log — don't
    // leak internal setting names to tenants who can't act on them.
    ec.logger.warn("SaaS Pay Now blocked for invoice ${saasInvoiceId}: RAZORPAY_KEY_ID/RAZORPAY_KEY_SECRET not set in ZETAERP company settings (SaaS Admin -> Settings -> Payment Gateway).")
    ec.message.addError("Online payment is temporarily unavailable. Please contact support to complete this payment.")
    return
}

context.razorpayKeyId = keyId
context.tenantName = tenant?.tenantName
context.adminEmail = tenant?.adminEmail

// Amount in paise (Razorpay requires smallest currency unit)
def amountPaise = (invoice.totalAmount * 100).longValueExact()
context.amount = amountPaise
context.currency = invoice.currencyUomId ?: "INR"

// Create Razorpay order via API
def auth = "${keyId}:${keySecret}".bytes.encodeBase64().toString()
// Reuse the invoice's existing order, including the legacy notes format. Replacing an
// in-flight order would lose a later capture notification and could charge the customer twice.
def existingOrder = invoice.gatewayOrderId ?: (invoice.notes?.startsWith('razorpay_order:') ? invoice.notes.substring(15) : null)
if (existingOrder) {
    if (!(existingOrder ==~ /order_[A-Za-z0-9]+/)) {
        ec.message.addError('Invalid payment order. Please contact support.'); return
    }
    def order
    try {
        def orderResponse = ec.service.rest().method('GET').uri('https://api.razorpay.com/v1/orders/' + existingOrder)
            .addHeader('Authorization','Basic ' + auth).call()
        order = orderResponse.statusCode == 200 ? orderResponse.jsonObject() : null
    } catch (Exception e) {
        ec.logger.warn('SaaS existing payment order lookup unavailable')
    }
    if (!order || order.id != existingOrder || order.amount != amountPaise || order.currency != context.currency
            || !(order.status in ['created','attempted'])) {
        ec.message.addError('This payment order cannot be retried. Please contact support to confirm its status.'); return
    }
    context.razorpayOrderId = existingOrder
    return
}
def restClient = ec.service.rest()
    .method("POST")
    .uri("https://api.razorpay.com/v1/orders")
    .addHeader("Authorization", "Basic ${auth}")
    .addHeader("Content-Type", "application/json")
    .jsonObject([
        amount: amountPaise,
        currency: context.currency,
        receipt: "SAAS_INV_${invoice.saasInvoiceId}",
        notes: [
            tenantId: invoice.tenantId,
            invoiceId: invoice.saasInvoiceId,
            tenantName: tenant?.tenantName ?: ''
        ]
    ])

def response
try { response = restClient.call() }
catch (Exception e) {
    ec.logger.warn('SaaS payment gateway request unavailable')
    ec.message.addError('Payment gateway is temporarily unavailable. Please try again later.'); return
}
if (response.statusCode == 200 || response.statusCode == 201) {
    def body = response.jsonObject()
    if (!body?.id || body.amount != amountPaise || body.currency != context.currency) {
        ec.message.addError('Payment gateway returned an invalid order. Please contact support.')
        return
    }
    context.razorpayOrderId = body.id

    // Store order ID on the invoice
    ec.service.sync().name("update#zenith.erp.saas.SaasInvoice")
        .parameter("saasInvoiceId", invoice.saasInvoiceId)
        .parameter("gatewayOrderId", body.id)
        .parameter("gatewayOrderAmount", invoice.totalAmount)
        .disableAuthz().call()
} else {
    ec.logger.error("Razorpay order creation failed (HTTP ${response.statusCode})")
    ec.message.addError("Payment gateway error. Please try again later.")
}

import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

context.success = false

def keySecret = ec.entity.find("zenith.erp.base.CompanySettings")
    .condition("organizationPartyId", "ZETAERP")
    .condition("settingKey", "RAZORPAY_KEY_SECRET").disableAuthz().one()?.settingValue

if (!keySecret) {
    ec.message.addError("Razorpay not configured")
    return
}

// Verify signature: HMAC-SHA256(razorpay_order_id + "|" + razorpay_payment_id, secret)
def payload = "${razorpay_order_id}|${razorpay_payment_id}"
def mac = Mac.getInstance("HmacSHA256")
mac.init(new SecretKeySpec(keySecret.getBytes("UTF-8"), "HmacSHA256"))
def computed = mac.doFinal(payload.getBytes("UTF-8"))
def expectedSig = computed.collect { String.format('%02x', it) }.join('')

if (!java.security.MessageDigest.isEqual(expectedSig.getBytes('UTF-8'), razorpay_signature.getBytes('UTF-8'))) {
    ec.logger.warn("Razorpay signature mismatch for order ${razorpay_order_id}")
    ec.message.addError("Payment verification failed. Please contact support.")
    return
}

// Signature valid — record payment
boolean d = ec.artifactExecution.disableAuthz()
try {
    def invoice = ec.entity.find("zenith.erp.saas.SaasInvoice")
        .condition("saasInvoiceId", saasInvoiceId).forUpdate(true).one()
    if (!invoice) {
        ec.message.addError("Invoice not found")
        return
    }

    // SECURITY: bind this payment to THIS invoice. create#RazorpayOrder recorded the order on the
    // invoice (notes = "razorpay_order:<id>") and created it for the invoice's amount; require
    // razorpay_order_id to match. Without this, a genuine (order|payment|signature) tuple from a
    // cheaper/unrelated payment could be replayed to mark ANY tenant's invoice paid. (Also binds amount.)
    def storedOrder = invoice.gatewayOrderId ?: (invoice.notes?.startsWith('razorpay_order:') ? invoice.notes.substring(15) : null)
    if (storedOrder != razorpay_order_id) {
        ec.logger.warn("Razorpay verify: order " + razorpay_order_id + " does not match invoice " + saasInvoiceId)
        ec.message.addError("Payment verification failed. Please contact support.")
        return
    }
    def existingPayment = ec.entity.find('zenith.erp.saas.SaasPayment').condition('gatewayPaymentId',razorpay_payment_id).one()
    if (invoice.statusId == 'SiPaid' && existingPayment?.saasInvoiceId == saasInvoiceId
            && existingPayment.gatewayOrderId == razorpay_order_id && existingPayment.statusId == 'SpSuccess') {
        context.success = true; context.saasPaymentId = existingPayment.saasPaymentId; return
    }
    if (!(invoice.statusId in ['SiSent','SiOverdue']) || invoice.totalAmount == null || invoice.totalAmount <= 0
            || (invoice.gatewayOrderAmount != null && invoice.gatewayOrderAmount != invoice.totalAmount)) {
        ec.message.addError('This invoice is not payable. Please contact support.'); return
    }
    if (!(razorpay_payment_id ==~ /pay_[A-Za-z0-9]+/)) {
        ec.message.addError('Invalid payment reference.'); return
    }
    def keyId = ec.entity.find('zenith.erp.base.CompanySettings').condition('organizationPartyId','ZETAERP')
        .condition('settingKey','RAZORPAY_KEY_ID').one()?.settingValue
    if (!keyId) { ec.message.addError('Online payment verification is temporarily unavailable. Please contact support.'); return }
    def auth = "${keyId}:${keySecret}".bytes.encodeBase64().toString()
    def paymentResponse
    try {
        paymentResponse = ec.service.rest().method('GET').uri('https://api.razorpay.com/v1/payments/' + razorpay_payment_id)
            .addHeader('Authorization','Basic ' + auth).call()
    } catch (Exception e) {
        ec.logger.warn('SaaS captured payment lookup unavailable')
        ec.message.addError('Payment verification is temporarily unavailable. Please contact support.'); return
    }
    def payment = paymentResponse.statusCode == 200 ? paymentResponse.jsonObject() : null
    if (!payment || payment.id != razorpay_payment_id || payment.order_id != storedOrder || payment.status != 'captured'
            || payment.amount != (invoice.totalAmount * 100).longValueExact() || payment.currency != (invoice.currencyUomId ?: 'INR')) {
        ec.message.addError('Payment has not been captured for this invoice. Please contact support.'); return
    }

    // IDEMPOTENCY: one gateway payment must never settle two invoices or be applied twice.
    def dupPay = ec.entity.find("zenith.erp.saas.SaasPayment")
        .condition("gatewayPaymentId", razorpay_payment_id).count()
    if (dupPay > 0) {
        ec.logger.warn("Razorpay verify: payment " + razorpay_payment_id + " already recorded")
        ec.message.addError("This payment has already been processed.")
        return
    }

    // Create payment record
    def payResult = ec.service.sync().name("create#zenith.erp.saas.SaasPayment")
        .parameter("saasInvoiceId", saasInvoiceId)
        .parameter("tenantId", invoice.tenantId)
        .parameter("paymentDate", ec.user.nowTimestamp)
        .parameter("amount", invoice.totalAmount)
        .parameter("currencyUomId", invoice.currencyUomId ?: "INR")
        .parameter("paymentGateway", "Razorpay")
        .parameter("gatewayPaymentId", razorpay_payment_id)
        .parameter("gatewayOrderId", razorpay_order_id)
        .parameter("statusId", "SpSuccess")
        .call()
    context.saasPaymentId = payResult.saasPaymentId

    // Mark invoice as paid
    ec.service.sync().name("update#zenith.erp.saas.SaasInvoice")
        .parameter("saasInvoiceId", saasInvoiceId)
        .parameter("statusId", "SiPaid")
        .parameter("paidDate", ec.user.nowTimestamp)
        .call()

    // Reactivate tenant if suspended
    def tenant = ec.entity.find("zenith.erp.saas.SaasTenant")
        .condition("tenantId", invoice.tenantId).one()
    if (tenant?.statusId == 'SaasTenantSuspended') {
        ec.service.sync().name("zenith.saas.SaasLifecycleServices.reactivate#AfterPayment")
            .parameter("tenantId", invoice.tenantId)
            .parameter("paymentId", razorpay_payment_id)
            .call()
    }

    // Audit log
    ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog")
        .parameter("tenantId", invoice.tenantId)
        .parameter("eventType", "PAYMENT_SUCCESS")
        .parameter("eventDate", ec.user.nowTimestamp)
        .parameter("description", "Payment of ${invoice.totalAmount} ${invoice.currencyUomId ?: 'INR'} via Razorpay (${razorpay_payment_id})")
        .call()

    context.success = true
} finally { if (!d) ec.artifactExecution.enableAuthz() }

import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

def webhookSecret = ec.entity.find("zenith.erp.base.CompanySettings")
    .condition("organizationPartyId", "ZETAERP")
    .condition("settingKey", "RAZORPAY_WEBHOOK_SECRET").disableAuthz().one()?.settingValue

if (!webhookSecret || !webhookSignature) {
    ec.logger.warn("Razorpay webhook: missing secret or signature")
    return
}

context.accepted = false
if (!webhookSignature || !rawBody) return
// Verify the exact bytes supplied by the public HTTP endpoint (before JSON parsing).
def mac = Mac.getInstance("HmacSHA256")
mac.init(new SecretKeySpec(webhookSecret.getBytes("UTF-8"), "HmacSHA256"))
def computed = mac.doFinal(rawBody.getBytes("UTF-8"))
def expectedSig = computed.collect { String.format('%02x', it) }.join('')

if (!java.security.MessageDigest.isEqual(expectedSig.getBytes('UTF-8'), webhookSignature.getBytes('UTF-8'))) {
    ec.logger.warn("Razorpay webhook: signature mismatch")
    return
}

def webhookBody
try { webhookBody = new groovy.json.JsonSlurper().parseText(rawBody) }
catch (Exception e) { return }
if (!(webhookBody instanceof Map)) return
// Only the signed raw body may supply business fields; ignore separately supplied maps.
context.accepted = true
def event = webhookBody?.event
def payload = webhookBody?.payload?.payment?.entity

if (!payload) return

ec.logger.info("Razorpay webhook: ${event} for payment ${payload.id}")

boolean d = ec.artifactExecution.disableAuthz()
try {
    if (event == 'payment.captured') {
        def orderId = payload.order_id
        if (!orderId || !payload.id || payload.status != 'captured') return
        def matches = ec.entity.find('zenith.erp.saas.SaasInvoice').condition('gatewayOrderId',orderId).limit(2).list()
        if (!matches) matches = ec.entity.find('zenith.erp.saas.SaasInvoice')
            .condition('notes','razorpay_order:' + orderId).limit(2).list() // Existing orders remain payable.
        if (matches.size() != 1) return
        def inv = ec.entity.find('zenith.erp.saas.SaasInvoice').condition('saasInvoiceId',matches[0].saasInvoiceId)
            .forUpdate(true).one()
        if (!(inv.statusId in ['SiSent','SiOverdue']) || inv.totalAmount == null || inv.totalAmount <= 0
                || payload.amount != (inv.totalAmount * 100).longValueExact()
                || payload.currency != (inv.currencyUomId ?: 'INR')
                || (inv.gatewayOrderAmount != null && inv.gatewayOrderAmount != inv.totalAmount)) return
        if (ec.entity.find('zenith.erp.saas.SaasPayment').condition('gatewayPaymentId',payload.id).count() > 0) return
        ec.service.sync().name('create#zenith.erp.saas.SaasPayment').parameters([
            saasInvoiceId:inv.saasInvoiceId, tenantId:inv.tenantId, paymentDate:ec.user.nowTimestamp,
            amount:inv.totalAmount, currencyUomId:inv.currencyUomId ?: 'INR', paymentGateway:'Razorpay',
            gatewayPaymentId:payload.id, gatewayOrderId:orderId, paymentMethod:payload.method, statusId:'SpSuccess']).call()
        ec.service.sync().name('update#zenith.erp.saas.SaasInvoice').parameters([
            saasInvoiceId:inv.saasInvoiceId, statusId:'SiPaid', paidDate:ec.user.nowTimestamp]).call()
        def tenant = ec.entity.find('zenith.erp.saas.SaasTenant').condition('tenantId',inv.tenantId).one()
        if (tenant?.statusId == 'SaasTenantSuspended') ec.service.sync()
            .name('zenith.saas.SaasLifecycleServices.reactivate#AfterPayment')
            .parameters([tenantId:inv.tenantId, paymentId:payload.id]).call()
        ec.service.sync().name('create#zenith.erp.saas.SaasAuditLog').parameters([
            tenantId:inv.tenantId, eventType:'PAYMENT_SUCCESS', eventDate:ec.user.nowTimestamp,
            description:'Captured subscription payment via Razorpay webhook']).call()
    } else if (event == 'payment.failed') {
        ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog")
            .parameter("eventType", "PAYMENT_FAILED")
            .parameter("eventDate", ec.user.nowTimestamp)
            .parameter("description", 'Razorpay reported a failed subscription payment').call()
    }
} finally { if (!d) ec.artifactExecution.enableAuthz() }

if (!ec.user.isInGroup('ADMIN')) { ec.message.addError('Only the platform administrator can record an offline payment.'); return }
boolean disabled = ec.artifactExecution.disableAuthz()
try {
    def invoice = ec.entity.find('zenith.erp.saas.SaasInvoice').condition('saasInvoiceId',saasInvoiceId).forUpdate(true).one()
    if (!invoice) { ec.message.addError('Invoice not found.'); return }
    if (invoice.statusId == 'SiPaid') return
    if (!(invoice.statusId in ['SiSent','SiOverdue']) || invoice.totalAmount == null || invoice.totalAmount <= 0) {
        ec.message.addError('This invoice is not payable.'); return
    }
    def reference = 'manual:' + invoice.saasInvoiceId
    ec.service.sync().name('create#zenith.erp.saas.SaasPayment').parameters([
        saasInvoiceId:invoice.saasInvoiceId, tenantId:invoice.tenantId, paymentDate:ec.user.nowTimestamp,
        amount:invoice.totalAmount, currencyUomId:invoice.currencyUomId ?: 'INR', paymentGateway:'Manual',
        gatewayPaymentId:reference, statusId:'SpSuccess']).call()
    ec.service.sync().name('update#zenith.erp.saas.SaasInvoice').parameters([
        saasInvoiceId:invoice.saasInvoiceId,statusId:'SiPaid',paidDate:ec.user.nowTimestamp]).call()
    ec.service.sync().name('zenith.saas.SaasLifecycleServices.reactivate#AfterPayment')
        .parameters([tenantId:invoice.tenantId,paymentId:reference]).call()
    ec.service.sync().name('create#zenith.erp.saas.SaasAuditLog').parameters([
        tenantId:invoice.tenantId,eventType:'MANUAL_PAYMENT',eventDate:ec.user.nowTimestamp,
        userId:ec.user.userId,description:'Platform administrator recorded offline payment for SaaS invoice ' + invoice.saasInvoiceId]).call()
} finally { if (!disabled) ec.artifactExecution.enableAuthz() }
